(() => {
  'use strict';
  const D=window.ORBITA_DATA;
  const F=window.ORBITA_FEATURES;
  const KEY='orbita_private_v1';
  const base={attempts:[],reviewed:[],savedFeed:[],feedViewed:[],exams:[],notes:{},customLinks:[],settings:{duration:'15'},started:null,imports:{calendar:null,notion:null,drive:null},dailyAttempts:[],simHistory:[],reviewLog:[],activeSim:null,contentEvents:[],unavailableContent:[],sessionSerial:0,privateCards:[]};
  const clone=x=>JSON.parse(JSON.stringify(x));
  let storageIssue='',storageConflict=false;
  function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return clone(base);const x=JSON.parse(raw);if(!F.validState(x))throw Error('formato inválido');return {...clone(base),...x,settings:{...base.settings,...x.settings},imports:{...base.imports,...x.imports}}}catch(e){storageIssue='O armazenamento não pôde ser lido. Exporte os dados originais antes de restaurar um backup ou apagar. Novas alterações não serão gravadas.';return clone(base)}}
  let db=load();
  let adaptivePlan=null,shownKey='';let feedOrderCache=new Map();
  function invalidateFeed(){feedOrderCache.clear();adaptivePlan=null;shownKey=''}
  let selectedVideo=null;let prepTopic='all',prepCount=5,prepStage='P2',dailyBlock=-1,feedConfidence=null;
  let page='home', dailyDate=F.academicClock().date, dailyReveal=false, dailyConfidence=null, dailyStatus=null, confidence=null, prepSubject='MEP230', examMode=null, selectedSubject=null, selectedTopic=null, selectedSubTab='topics', selectedQuiz='all', quizIndex=0, picked=null, assessed=false, hinted=false, reveal=false, flashFilter='all', flashIndex=0, flashFlipped=false, feedIndex=0, feedFilter='all', feedSavedOnly=false, feedPick=null, feedAssessed=false, feedTimer=null, tick=null, modal=null, focusForStudy=null;
  const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',feed:'<rect x="3" y="4" width="18" height="16" rx="4"/><path d="m10 8 6 4-6 4z"/>',book:'<path d="M12 7v14m0-14C9 4 5 4 2 5v15c4-1 7-1 10 1m0-14c3-3 7-3 10-2v15c-4-1-7-1-10 1"/>',quiz:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h4"/>',chart:'<path d="M4 20V11m6 9V5m6 15v-7m4 7V9"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-2 2-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21H9v-.1a1.65 1.65 0 0 0-1-1.51 1.65 1.65 0 0 0-1.82.33l-.06.06-2-2 .06-.06A1.65 1.65 0 0 0 4.5 15a1.65 1.65 0 0 0-1.5-1H3v-4h.1a1.65 1.65 0 0 0 1.5-1 1.65 1.65 0 0 0-.33-1.82l-.06-.06 2-2 .06.06A1.65 1.65 0 0 0 8 4.5a1.65 1.65 0 0 0 1-1.5V3h6v.1a1.65 1.65 0 0 0 1 1.5 1.65 1.65 0 0 0 1.82-.33l.06-.06 2 2-.06.06A1.65 1.65 0 0 0 19.5 9a1.65 1.65 0 0 0 1.5 1H21v4h-.1a1.65 1.65 0 0 0-1.5 1z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',more:'<path d="m9 18 6-6-6-6"/>',play:'<path d="m8 5 12 7-12 7z"/>',star:'<path d="m12 3 2.8 5.7L21 9.6l-4.5 4.4 1 6.2-5.5-2.9-5.5 2.9 1-6.2L3 9.6l6.2-.9z"/>',check:'<path d="m5 12 4 4L19 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v4h16v-4"/>',download:'<path d="M12 4v13m-5-5 5 5 5-5M4 20h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',external:'<path d="M14 4h6v6m0-6-9 9"/><path d="M20 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h5"/>',flash:'<rect x="3" y="5" width="16" height="15" rx="2"/><path d="M7 2h14v15"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',close:'<path d="M6 6l12 12M18 6 6 18"/>',pause:'<path d="M9 5v14m6-14v14"/>'};
  const icon=(name,cls='')=>`<span class="glyph ${cls}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg></span>`;
  const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const attr=esc;
  const subj=id=>D.subjects.find(s=>s.id===id);
  function writeState(candidate,force=false){
    if((storageIssue||storageConflict)&&!force){showToast('Não salvo: resolva o aviso de armazenamento e exporte um backup.');return false}
    try{localStorage.setItem(KEY,JSON.stringify(candidate));return true}catch(e){storageIssue='Não foi possível salvar. Seu progresso está apenas nesta aba: exporte um backup antes de fechar.';showToast('Não salvo: exporte um backup antes de sair.');render();return false}
  }
  function captureSim(){if(examMode&&!examMode.finished)db.activeSim={...examMode,index:quizIndex,picked,assessed,hinted,reveal,confidence}}
  function save(){captureSim();return writeState(db)}
  const today=()=>F.academicClock().date;
  const calendarEvents=(date=today())=>F.studyEvents(db.imports.calendar,D.subjects).filter(e=>e.date===date);
  function chosenBlock(){if(dailyBlock>=0)return dailyBlock;const events=calendarEvents(dailyDate),clock=F.academicClock().time;return dailyDate===today()?Math.max(0,events.findIndex(e=>(e.end||e.start)>=clock)):0}
  const errorsFor=(sub)=>(db.imports.notion?.error_records||[]).filter(e=>F.activeError(e)&&(!sub||e.subject===sub));
  const privateFolder=(sub)=>db.imports.drive?.subjects?.find(x=>x.code===sub)?.drive_folder||null;
  const privateSources=(sub)=>db.imports.drive?.verified_documents?.filter(x=>x.subject===sub)||[];
  const privateBadge=(name)=>db.imports[name]?`${String(db.imports[name].source||'').includes('OAuth')?'Sincronizado':'Importado'} em ${esc(db.imports[name].captured_at||'data não informada')} · cópia local para offline; atualize pela conexão ou importação`:'Não importado · sem conexão ao vivo';
  const percent=(a,b)=>b?Math.round(100*a/b):0;
  const attempts=(sub,topic)=>db.attempts.filter(a=>(!sub||a.subject===sub)&&(!topic||a.topic===topic));
  const done=(sub,topic)=>attempts(sub,topic).filter(a=>a.origin!=='reveal').length;
  const uniqueDone=()=>new Set(db.attempts.map(a=>a.qid)).size;
  const accurate=(sub,topic)=>{let a=attempts(sub,topic).filter(a=>a.origin!=='reveal');return a.length?percent(a.filter(x=>x.correct&&!x.help).length,a.length):null};
  const weakTopics=()=>{let m=new Map();for(const a of db.attempts){if(a.origin==='reveal')continue;const k=a.subject+'|'+a.topic;if(!m.has(k))m.set(k,{subject:a.subject,topic:a.topic,total:0,wrong:0});const v=m.get(k);v.total++;if(a.origin!=='reveal'&&(!a.correct||a.help||a.confidence<75))v.wrong++;}return [...m.values()].filter(x=>x.wrong).sort((a,b)=>b.wrong/a.total-a.wrong/b.total)};
  function showToast(msg){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.textContent=msg;document.body.appendChild(n);setTimeout(()=>n.remove(),2500)}
  function navigate(p,options={}){captureSim();if(p==='feed'&&page!=='feed'){invalidateFeed();feedIndex=0;resetFeed();}if(p!=='quiz'&&p!=='sim-result')examMode=null;page=p; if(options.subject!==undefined){selectedSubject=options.subject;selectedTopic=null;selectedSubTab='topics'} if(options.topic!==undefined)selectedTopic=options.topic; if(options.quiz!==undefined){resetQuiz();selectedQuiz=options.quiz;quizIndex=0;} if(options.feed!==undefined){feedFilter=options.feed;feedIndex=0;resetFeed()} if(window.history&&location.hash!=='#'+p)window.history.pushState({subject:selectedSubject,topic:selectedTopic,tab:selectedSubTab},'','#'+p);render();window.scrollTo({top:0,behavior:'auto'})}
  const latestAttempts=()=>F.latest(db.attempts);
  const rankedQuestions=sub=>F.rankQuestions(D.questions.filter(q=>q.subject===sub),db,today(),prepTopic);
  const qpool=()=>{if(examMode?.ids)return examMode.ids.map(id=>D.questions.find(q=>q.id===id));const pool=D.questions.filter(x=>selectedQuiz==='all'||x.subject===selectedQuiz);if(!focusForStudy)return pool.length?pool:D.questions;const narrowed=pool.filter(x=>x.topic===focusForStudy);return narrowed.length?narrowed:pool.length?pool:D.questions};
  function resetQuiz(){picked=null;assessed=false;hinted=false;reveal=false;confidence=null;focusForStudy=null}
  function resetFeed(){feedPick=null;feedAssessed=false;feedConfidence=null}
  const daysUntil=dt=>{const t=new Date(String(dt)+'T12:00:00');return Math.round((t-new Date(today()+'T12:00:00'))/86400000)};
  const examsUpcoming=()=>db.exams.filter(x=>daysUntil(x.date)>=0).sort((a,b)=>a.date.localeCompare(b.date));
  function render(){
    const app=document.getElementById('app');
    app.innerHTML=`<div class="shell"><header class="head"><a href="#home" class="brand" data-page="home"><span class="brandlogo">◎</span><span>órbita<small>ESTUDOS · FEI</small></span></a><div class="headright"><button aria-label="Configurações" data-page="settings" class="iconbtn">${icon('settings')}</button></div></header><main class="main">${systemBanner()}${view()}</main><footer class="footer">Órbita v${D.version} · Seus registros ficam neste dispositivo · Conteúdo inicial autoral</footer></div>${nav()}${modal?modalHTML():''}`;
    if(window.ORBITA_SIMS)document.querySelectorAll?.('[data-sim]').forEach(el=>window.ORBITA_SIMS.update(el));if(page==='settings')window.ORBITA_CONNECTIONS?.mount();if(page==='feed')initFeedTimer();else stopTimer();
  }
  function nav(){let tabs=[['home','home','Início'],['daily','target','Hoje'],['feed','feed','Para você'],['study','book','Estudar'],['progress','chart','Progresso']];return `<nav class="nav" aria-label="Navegação">${tabs.map(([p,ico,label])=>`<button class="${page===p||page==='subject'&&p==='study'?'active':''}" data-page="${p}" aria-label="${label}"><span class="navicon">${icon(ico)}</span>${label}</button>`).join('')}</nav>`}
  function view(){switch(page){case 'videos':return viewVideos();case 'home':return viewHome();case 'daily':return viewDaily();case 'grades':return viewGrades();case 'prep':return viewPrep();case 'sim-result':return viewSimResult();case 'study':return viewStudy();case 'subject':return viewSubject();case 'quiz':return viewQuiz();case 'feed':return viewFeed();case 'progress':return viewProgress();case 'plan':return viewPlan();case 'settings':return viewSettings();case 'flash':return viewFlash();default:return viewHome()}}
  const metric=(label,v,sub='')=>`<div class="stat"><label>${label}</label><strong>${v}</strong><small>${sub}</small></div>`;
  function viewHome(){let total=db.attempts.filter(a=>a.origin!=='reveal').length,acc=accurate(null,null),n=examsUpcoming()[0],focus=weakTopics()[0];return `<div class="hero"><div class="heroGlow"></div><span class="eyebrow"><span class="dot"></span> SEU AMBIENTE DE ESTUDOS</span><h1>Aprender um pouco.<br>Dominar cada vez mais.</h1><p>Estude para as provas da FEI ou descubra Engenharia de um jeito leve, no seu tempo livre.</p><div class="actions"><button class="btn" data-page="feed">${icon('play')} Explorar For You</button><button class="btn secondary" data-page="quiz">${icon('target')} Treinar agora</button></div></div><div class="stats">${metric('Exercícios feitos',total,'tentativas registradas')}${metric('Acertos sem ajuda',acc===null?'—':acc+'%','calculado de respostas')}${metric('Matérias',D.subjects.length,'catalogadas')}</div><div class="section"><div class="secthead"><h2>Seu próximo passo</h2><button class="sectionlink" data-page="plan">Plano de provas →</button></div><div class="card">${n?`<div class="eyebrow">PRÓXIMA AVALIAÇÃO</div><h3 style="margin-top:11px">${esc(n.title)}</h3><p>${esc(subj(n.subject)?.name||n.subject)} · ${esc(n.date)} · ${daysUntil(n.date)} dia(s)</p><button data-page="plan" class="btn secondary sm">Ver planejamento ${icon('arrow')}</button>`:`<h3>Organize sua preparação para a P2</h3><p>Adicione as datas das suas próximas avaliações. O sistema ajudará a organizar as revisões, sem inventar notas ou prazos.</p><button class="btn sm" data-act="new-exam">${icon('clock')} Cadastrar prova</button>`}${focus?`<div class="divider"></div><span class="badge gold">Reteste recomendado</span><p><strong>${esc(focus.topic)}</strong> · ${esc(subj(focus.subject)?.short)}</p><button class="btn ghost sm" data-act="retest-topic" data-sub="${focus.subject}" data-topic="${attr(focus.topic)}">Revisar erro ${icon('arrow')}</button>`:''}</div></div>${dailyTeaser()}${db.activeSim?resumeCard():''}<section class="section"><div class="secthead"><h2>Suas disciplinas</h2><button class="sectionlink" data-page="study">Ver todas →</button></div><div class="subjectgrid">${D.subjects.map(s=>subjectCard(s)).join('')}</div></section><section class="section"><div class="secthead"><h2>Aprenda do seu jeito</h2></div><div class="two"><button class="topiccard" data-page="feed"><span><strong>For You de Engenharia</strong><span>Descobertas, desafios e simulações rápidas</span></span><span class="chev">→</span></button><button class="topiccard" data-page="flash"><span><strong>Revisão com flashcards</strong><span>Recupere conceitos da memória</span></span><span class="chev">→</span></button></div></section><div class="section notice">Biblioteca inicial preparada por tópicos. Os arquivos originais permanecem no seu Google Drive; eles não foram todos importados para dentro do app.</div>`}
  function subjectCard(s){const a=attempts(s.id); const ac=accurate(s.id);return `<button class="subject" data-act="open-sub" data-sub="${s.id}" style="text-align:left;color:inherit"><span class="subemoji" style="color:${s.accent}">${s.emoji}</span><span><span class="subcode">${s.id}${s.project?' · PROJETO':''}</span><span class="subname" style="display:block;margin-top:5px">${esc(s.name)}</span></span><span class="subsmall">${s.topics.length} tópicos · ${a.length} tentativas</span><div class="progressrail"><div class="progressbar" style="width:${ac??0}%"></div></div></button>`}
  function viewStudy(){return `<div class="pagehead"><span class="eyebrow">BIBLIOTECA ACADÊMICA</span><h1>Suas matérias</h1><p>Conteúdos estruturados, exercícios autorais e atalhos para as pastas originais do Drive acadêmico.</p></div><div class="subjectgrid">${D.subjects.map(subjectCard).join('')}</div><div class="section actions"><button class="btn secondary" data-page="videos">Vídeos acadêmicos</button></div><div class="section card"><h3>Como os materiais são utilizados?</h3><p>Os tópicos refletem o planejamento e os materiais identificados. Os links privados são exibidos somente após importação local; nem todos os arquivos foram lidos ou verificados. O tutor offline usa um banco original de questões, não reproduz automaticamente o conteúdo de todos os arquivos.</p></div>`}
  function viewSubject(){const s=subj(selectedSubject)||D.subjects[0];const tab=selectedSubTab;const topic=s.topics.find(t=>t[0]===selectedTopic); const links=privateSources(s.id).map(x=>({subject:s.id,title:x.title,type:'Drive',status:x.verified||'Referência',url:x.url}));const folder=privateFolder(s.id);return `<div class="row" style="margin-bottom:18px"><button class="backbtn" data-page="study" aria-label="Voltar">${icon('back')}</button><span class="eyebrow">${s.id}</span></div><div class="pagehead"><h1>${s.emoji} ${esc(s.name)}</h1><p>${s.topics.length} tópicos para preparar ${s.project?'as entregas':'suas avaliações'}.</p><div class="actions"><button class="btn sm" data-act="sub-quiz" data-sub="${s.id}">Treinar ${icon('arrow')}</button>${folder?`<a target="_blank" rel="noopener noreferrer" href="${attr(/^https:\/\//i.test(folder)?folder:'#')}" class="btn secondary sm">Pasta Drive ${icon('external')}</a>`:`<button class="btn secondary sm" data-page="settings">Importar links do Drive</button>`}</div></div><div class="chips">${[['topics','Tópicos'],['materials','Materiais'],['notes','Minhas notas']].map(([x,n])=>`<button class="chip ${tab===x?'on':''}" data-act="sub-tab" data-tab="${x}">${n}</button>`).join('')}</div>${tab==='topics'?(topic?`<div class="card"><span class="eyebrow">CONCEITO · ${s.id}</span><h3 style="margin-top:9px">${esc(topic[0])}</h3><p>${esc(topic[1])}</p><div class="notice">Aprenda a identificar o fenômeno e as hipóteses antes de substituir valores em fórmulas. Este cartão é uma síntese introdutória original; consulte o material do professor para a resolução completa.</div><div class="actions"><button class="btn sm" data-act="topic-quiz" data-sub="${s.id}" data-topic="${attr(topic[0])}">Questões deste tópico</button><button class="btn secondary sm" data-act="topic-note" data-sub="${s.id}" data-topic="${attr(topic[0])}">Adicionar anotação</button><button class="btn ghost sm" data-act="clear-topic">Voltar aos tópicos</button></div></div>`:`<div class="stack">${s.topics.map((t,i)=>`<button class="topiccard" data-act="open-topic" data-topic="${attr(t[0])}"><span><strong>${String(i+1).padStart(2,'0')} · ${esc(t[0])}</strong><span>${esc(t[1])}</span></span><span class="chev">›</span></button>`).join('')}</div>`):tab==='materials'?`<div class="stack">${folder?`<a class="resource" href="${attr(/^https:\/\//i.test(folder)?folder:'#')}" target="_blank" rel="noopener noreferrer">${icon('book')}<span class="grow"><strong>Pasta principal ${s.id} no Google Drive</strong><small>Link importado privadamente neste dispositivo</small></span>${icon('external')}</a>`:`<div class="notice">Importe o arquivo pessoal de links em Configurações. Nenhum endereço privado está incluído no site público.</div>`}${links.map(l=>`<a class="resource" href="${attr(/^https:\/\//i.test(l.url)?l.url:'#')}" target="_blank" rel="noopener noreferrer">${icon('flash')}<span class="grow"><strong>${esc(l.title)}</strong><small>${esc(l.type)} · ${esc(l.status)}</small></span>${icon('external')}</a>`).join('')}${db.customLinks.filter(l=>l.subject===s.id).map(l=>`<a class="resource" href="${attr(/^https:\/\//i.test(l.url)?l.url:'#')}" target="_blank" rel="noopener noreferrer">${icon('external')}<span class="grow"><strong>${esc(l.title)}</strong><small>Adicionado por você</small></span></a>`).join('')}<button class="btn secondary" data-act="new-link" data-sub="${s.id}">Adicionar link de material</button><div class="help">Os links do Drive podem solicitar login. Os PDFs ainda não são baixados nem indexados automaticamente no Órbita.</div></div>`:`<div class="stack">${s.topics.map(t=>`<div class="card"><strong>${esc(t[0])}</strong><p>${esc(db.notes[s.id+'|'+t[0]]||'Nenhuma anotação ainda.')}</p><button class="btn secondary sm" data-act="topic-note" data-sub="${s.id}" data-topic="${attr(t[0])}">Editar nota</button></div>`).join('')}</div>`}`}
  function viewQuiz(){const list=qpool();const q=list[quizIndex%list.length];if(!q)return '<div class="empty">Sem questões nesta seleção. <button class="btn" data-page="prep">Configurar simulado</button></div>';let answered=assessed||reveal;const attemptsToday=db.attempts.filter(a=>a.date===today()).length;return `<div class="pagehead"><span class="eyebrow">PRATIQUE E APRENDA</span><h1>Exercícios</h1><p>Responda antes de consultar a explicação. Quando precisar de ajuda, registraremos isso para priorizar a revisão.</p></div><div class="chips ${examMode?'hide':''}"><button class="chip ${selectedQuiz==='all'?'on':''}" data-act="quiz-filter" data-sub="all">Todas</button>${D.subjects.map(s=>`<button class="chip ${selectedQuiz===s.id?'on':''}" data-act="quiz-filter" data-sub="${s.id}">${s.emoji} ${s.short}</button>`).join('')}</div><div class="row between" style="margin-bottom:13px"><span class="tiny">${list.length} questões disponíveis nesta seleção</span><span class="pill">Hoje: ${attemptsToday} tentativas</span></div><section class="quizbox"><span class="eyebrow">${esc(subj(q.subject)?.short)} · ${esc(q.topic)}</span><div class="row between"><span class="badge">Nível ${q.difficulty}/3</span><span class="questioncounter">${(quizIndex%list.length)+1} de ${list.length}</span></div><h2>${esc(q.q)}</h2>${q.choices.map((t,i)=>`<button class="choice ${picked===i?'chosen':''} ${answered?(i===q.answer?'right':picked===i?'wrong':''):''}" data-act="pick" data-choice="${i}" ${answered?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(t)}</span></button>`).join('')}${examMode?`<div class="notice">Simulado autoral · ${Math.min(quizIndex+1,examMode.limit)} de ${examMode.limit} · sem consulta é a melhor evidência de preparo.</div>`:''}${hinted?`<div class="hint"><strong>Dica:</strong> ${esc(q.hint)}</div>`:''}${answered?`<div class="explanation ${assessed&&picked!==q.answer?'bad':''}"><strong>${reveal?'Resposta explicada':picked===q.answer?'Resposta correta':'Vamos revisar'}</strong>${correction(q,picked)}<p>${esc(F.feedback(db.attempts.at(-1)||{}))}</p>${errorEditor(q)}<span class="tiny" style="display:block;margin-top:10px">Questão autoral de treinamento; não é enunciado oficial da FEI.</span></div>`:''}${!answered?`<div class="confidence-panel"><strong>Qual sua confiança nesta resposta?</strong><div class="chips">${[20,50,75,100].map(n=>`<button class="chip ${confidence===n?'on':''}" data-act="confidence" data-value="${n}">${n}%</button>`).join('')}</div></div>`:''}<div class="quiztools"><button class="btn secondary sm" data-act="hint" ${answered?'disabled':''}>${icon('target')} Pedir dica</button>${!answered?`<div class="actions"><button class="btn ghost sm" data-act="reveal">Ver resolução</button><button class="btn sm" data-act="assess" ${picked===null||confidence===null?'disabled':''}>Corrigir</button></div>`:`<button class="btn sm" data-act="next-quiz">${examMode&&quizIndex+1>=examMode.limit?'Finalizar simulado':'Próximo exercício'} ${icon('arrow')}</button>`}</div></section><div class="section card"><h3>Tutor por etapas, sem API</h3><p>Use “Pedir dica” para tentar resolver sozinho antes da explicação. Esta primeira versão possui tutor guiado baseado nas questões preparadas. Um chatbot capaz de interpretar exercícios inéditos ou fotos exigirá uma integração de IA separada.</p></div>`}
  function record(q,choice,help=false,origin='quiz',confidenceValue=null){
    const correct=choice!==null&&choice===q.answer,previous=latestAttempts().find(a=>a.qid===q.id);
    const item={id:String(Date.now())+'-'+Math.random().toString(36).slice(2),qid:q.id,concept:q.concept||null,subject:q.subject,topic:q.topic,correct,choice,help:!!help,origin,confidence:confidenceValue,date:today(),timestamp:new Date().toISOString(),...F.schedule(previous,correct,help,confidenceValue,today()),...(examMode?{simId:examMode.id}:{} )};
    db.attempts.push(item);db.reviewLog.push({id:item.id,subject:q.subject,topic:q.topic,date:today(),source:origin,outcome:origin==='reveal'?'consulta':correct?'acerto':'erro',reviewDue:item.reviewDue});
    // O ranking do cartão atual fica estável até a próxima sessão; responder nunca troca o cartão sob o aluno.
    save();
  }
  function pickQuiz(i){if(assessed||reveal)return;picked=i;save();render()}
  function assessQuiz(){const q=qpool()[quizIndex%qpool().length];if(assessed||reveal||picked===null||confidence===null)return;assessed=true;record(q,picked,hinted,'quiz',confidence);render()}
  function nextQuiz(){if(!assessed&&!reveal)return;if(examMode&&quizIndex+1>=examMode.limit){
    const items=db.attempts.filter(a=>a.simId===examMode.id);
    if(!db.simHistory.some(h=>h.id===examMode.id))db.simHistory.push({id:examMode.id,subject:examMode.subject,stage:examMode.stage,topic:examMode.topic,date:today(),attemptIds:items.map(a=>a.id),correct:items.filter(a=>a.correct&&!a.help).length,total:items.length});
    examMode.finished=true;db.activeSim=null;save();navigate('sim-result');return;
  }quizIndex++;picked=null;assessed=false;hinted=false;reveal=false;confidence=null;save();render()}
  function chooseFeed(){if(window.ORBITA_CATALOG?.current){if(!adaptivePlan){db.sessionSerial=(db.sessionSerial||0)+1;adaptivePlan=window.ORBITA_RECOMMEND.plan({...window.ORBITA_CATALOG.current,items:[...window.ORBITA_CATALOG.current.items,...db.privateCards]},db,{minutes:Number(db.settings.duration),subject:feedFilter,savedOnly:feedSavedOnly,online:navigator.onLine!==false,seed:String(db.sessionSerial)+'-'+Date.now()});save()}const ids=adaptivePlan.queue.map(x=>x.id);return ids.map(id=>[...D.feed,...db.privateCards.map(x=>({...x,topic:x.title,type:'lesson'}))].find(x=>x.id===id)).filter(Boolean)}let list=D.feed.filter(f=>(feedFilter==='all'||f.subject===feedFilter)&&(!feedSavedOnly||db.savedFeed.includes(f.id)));const key=feedFilter+'|'+feedSavedOnly;if(!feedOrderCache.has(key)){const priorities=weakTopics();const weakSet=new Set(priorities.slice(0,4).map(x=>x.subject+'|'+x.topic));const todaySubjects=new Set(calendarEvents().map(e=>e.subject));const notionSubjects=new Set(errorsFor().map(e=>e.subject));const upcoming=examsUpcoming()[0];list=[...list].sort((a,b)=>{const score=x=>(weakSet.has(x.subject+'|'+x.topic)?4:0)+(todaySubjects.has(x.subject)?5:0)+(notionSubjects.has(x.subject)?1:0)+(upcoming&&x.subject===upcoming.subject?2:0)+(db.savedFeed.includes(x.id)?-.2:0);return score(b)-score(a)});feedOrderCache.set(key,list.map(x=>x.id));}else{const ids=feedOrderCache.get(key);list.sort((a,b)=>ids.indexOf(a.id)-ids.indexOf(b.id))}return list}
  function viewFeed(){const list=chooseFeed(),f=list[feedIndex%Math.max(1,list.length)];if(f&&adaptivePlan&&shownKey!==adaptivePlan.seed+'|'+f.id){shownKey=adaptivePlan.seed+'|'+f.id;contentEvent(f,'shown')}if(f&&!db.feedViewed.includes(f.id)){db.feedViewed.push(f.id);save()}if(!f)return `<div class="pagehead"><h1>Para você</h1></div><div class="empty">Nenhum conteúdo elegível agora. O controle de repetição pode ter esgotado esta seleção; escolha outras disciplinas ou retorne após o intervalo. <button class="btn sm" data-act="feed-reset">Mostrar tudo</button></div>`; const s=subj(f.subject),q=D.questions.find(q=>q.id===f.id)||D.questions.find(q=>q.subject===f.subject&&q.topic===f.topic);let recommended=weakTopics().some(x=>x.subject===f.subject&&x.topic===f.topic)?'Prioridade: assunto com erro registrado':examsUpcoming().some(e=>e.subject===f.subject)?'Relacionada a uma prova cadastrada':'Conteúdo de sua biblioteca';const existing=db.attempts.filter(a=>a.feedId===f.id).at(-1);if(existing&&existing.reviewDue>today()&&!feedAssessed){feedPick=existing.choice;feedAssessed=true;feedConfidence=existing.confidence;}const isSaved=db.savedFeed.includes(f.id);const result=feedAssessed&&q?`<div class="explanation ${feedPick!==q.answer?'bad':''}"><strong>${feedPick===q.answer?'Acertou!':'Revisão rápida'}</strong>${correction(q,feedPick)}</div>`:'';
   return `<div class="pagehead"><span class="eyebrow">APRENDA NOS INTERVALOS</span><h1>Para você</h1><p>Conteúdos curtos para explorar, entender e testar. Você decide quando encerrar.</p></div><div class="feed-wrap">${adaptivePlan?.insufficient?'<div class="notice">Não há conteúdo elegível suficiente para a duração escolhida. Não vamos repetir itens só para preencher tempo.</div>':''}<div class="feed-top"><span class="badge gold">${feedSavedOnly?'Itens salvos':'Recomendados para você'}</span>${feedTimer?'<button class="btn secondary sm" data-act="end-session">Encerrar</button>':''}<button class="btn ghost sm" data-act="session-options">${icon('clock')} ${feedTimer?'Sessão ativa':'Definir sessão'}</button></div>${feedTimer?`<div class="today" id="timer-info" style="margin-bottom:12px">Sessão em andamento · ${esc(db.settings.duration)} minutos planejados</div>`:''}<div class="chips"><button class="chip ${feedFilter==='all'?'on':''}" data-act="feed-filter" data-sub="all">Tudo</button>${D.subjects.map(s=>`<button class="chip ${feedFilter===s.id?'on':''}" data-act="feed-filter" data-sub="${s.id}">${s.emoji} ${s.short}</button>`).join('')}</div><div class="feedviewport" id="feed-swipe"><div class="feedart"><div class="art-grid"></div><div class="art-ring"></div>${visualDiagram(f)}</div><div class="feedbody"><span class="eyebrow">${esc(s.short)} · ${esc(f.type.replace('_',' '))}</span><h2>${esc(f.title)}</h2><p>${esc(f.body)}</p>${f.type==='sim_engine'?window.ORBITA_SIMS.render(f.simulationId):f.type==='video'?videoCard(f):f.type==='sim_nat'?simNatural():f.type==='sim_heat'?simHeat():f.type==='quiz'&&q?`<div class="sim"><span class="eyebrow">DESAFIO RÁPIDO</span><strong style="display:block;margin:10px 0;font-size:14px;line-height:1.4">${esc(q.q)}</strong>${q.choices.map((c,i)=>`<button data-act="feed-answer" data-choice="${i}" class="choice ${feedPick===i?'chosen':''} ${feedAssessed?(i===q.answer?'right':feedPick===i?'wrong':''):''}" ${feedAssessed||feedConfidence===null?'disabled':''}><span class="letter">${'ABCD'[i]}</span>${esc(c)}</button>`).join('')}${!feedAssessed?`<div class="confidence-panel"><strong>Confiança antes da correção</strong><div class="chips">${[20,50,75,100].map(n=>`<button class="chip ${feedConfidence===n?'on':''}" data-act="feed-confidence" data-value="${n}">${n}%</button>`).join('')}</div><span class="tiny">Escolha a confiança e depois uma resposta.</span></div>`:''}${result}</div>`:`<div class="today">${esc(adaptivePlan?.queue.find(x=>x.id===f.id)?.reason||recommended)}</div><button class="btn secondary sm" data-act="complete-content" data-id="${f.id}">Concluí esta atividade</button>`}<div class="row between wrap"><button class="btn secondary sm" data-act="feed-study" data-sub="${f.subject}" data-topic="${attr(f.topic)}">Estudar este assunto ${icon('arrow')}</button><span class="tiny">${feedIndex+1} de ${list.length}</span></div></div><div class="feedcontrols"><div class="row"><button class="iconbtn" data-act="save-feed" data-id="${f.id}" aria-label="${isSaved?'Remover dos salvos':'Salvar para revisão'}" title="${isSaved?'Remover dos salvos':'Salvar'}" style="color:${isSaved?'var(--gold)':'inherit'}">${icon('star')}</button><button class="iconbtn" data-act="feed-save-filter" aria-label="Mostrar salvos" title="Mostrar salvos">${icon('book')}</button></div><div class="row"><button class="btn secondary sm" data-act="prev-feed" ${feedIndex<=0?'disabled':''}>Anterior</button><button class="btn sm" data-act="next-feed">Próximo ${icon('arrow')}</button></div></div></div><div class="feedfoot"><span class="tiny">Deslize para cima/baixo ou use os botões para trocar de conteúdo.</span></div><div class="section card"><h3>Sobre suas recomendações</h3><p>O Órbita prioriza erros e provas próximas. Nenhuma recomendação é baseada em prender sua atenção por mais tempo. O feed é finito e pode ser encerrado quando quiser.</p></div></div>`}
  function simNatural(){return `<div class="sim"><div class="eyebrow">SIMULADOR · 1 GDL</div><label for="mass">Massa <strong><span id="massnum">4</span> kg</strong></label><input id="mass" data-act="sim-range" type="range" min="1" max="12" step="1" value="4"/><label for="stiff">Rigidez <strong><span id="stiffnum">400</span> N/m</strong></label><input id="stiff" data-act="sim-range" type="range" min="100" max="1200" step="100" value="400"/><div class="divider"></div><span class="big" id="naturalfreq">10,00</span> <span class="units">rad/s</span><div class="tiny">ωn = √(k/m) · Modelo ideal sem amortecimento</div></div>`}
  function simHeat(){return `<div class="sim"><div class="eyebrow">SIMULADOR · LEI DE FOURIER</div><label for="width">Espessura L <strong><span id="widthnum">0,10</span> m</strong></label><input id="width" data-act="sim-range" type="range" min="0.05" max="0.5" step="0.05" value="0.1"/><label for="cond">Condutividade k <strong><span id="condnum">2</span> W/(m·K)</strong></label><input id="cond" data-act="sim-range" type="range" min="0.5" max="5" step="0.5" value="2"/><div class="divider"></div><span class="big" id="heatflow">600,00</span> <span class="units">W</span><div class="tiny">Q = kAΔT/L, com A = 1 m² e ΔT = 30 K</div></div>`}
  function nextFeed(delta){const l=chooseFeed();if(!l.length)return;if(delta>0&&feedIndex+1>=l.length){feedTimer=null;stopTimer();modal={type:'summary'};render();return;}feedIndex=Math.max(0,feedIndex+delta);resetFeed();const f=l[feedIndex];if(!db.feedViewed.includes(f.id)){db.feedViewed.push(f.id);save()}render()}
  function viewFlash(){const list=flashPool();const f=list[flashIndex%Math.max(1,list.length)];return `<div class="pagehead"><span class="eyebrow">REVISÃO ATIVA</span><h1>Flashcards</h1><p>Tente lembrar antes de virar. A revisão funciona sem inteligência artificial externa.</p></div><div class="chips"><button class="chip ${flashFilter==='all'?'on':''}" data-act="flash-filter" data-sub="all">Todas</button>${D.subjects.map(s=>`<button class="chip ${flashFilter===s.id?'on':''}" data-act="flash-filter" data-sub="${s.id}">${s.short}</button>`).join('')}</div>${f?`<div class="row between" style="margin:10px 0 12px"><span class="eyebrow">${esc(subj(f.subject).short)}</span><span class="tiny">${flashIndex+1}/${list.length}</span></div><button class="flashcard" data-act="flip-flash" style="width:100%;color:inherit"><span>${flashFlipped?'RESPOSTA':'PERGUNTA'} · ${esc(f.topic)}</span><p>${esc(flashFlipped?f.back:f.front)}</p><span>Toque para ${flashFlipped?'voltar':'revelar'}</span></button><div class="actions" style="justify-content:center;margin-top:16px">${flashFlipped?`<button class="btn secondary" data-act="mark-flash" data-known="no">Revisar depois</button><button class="btn" data-act="mark-flash" data-known="yes">Lembrei sozinho ${icon('check')}</button>`:`<button class="btn" data-act="flip-flash">Revelar resposta</button>`}</div>`:`<div class="empty">Nenhum cartão nesta seleção.</div>`}<div class="section card"><h3>O que conta como aprendizado?</h3><p>Relembrar a resposta sem consultar é melhor evidência de domínio do que apenas visualizar o cartão. Reteste os assuntos mais difíceis depois de alguns dias.</p></div>`}
  function viewProgress(){const all=db.attempts,acc=accurate(),weak=weakTopics(),dailies=[...new Set(all.map(a=>a.date))].length;return `<div class="pagehead"><span class="eyebrow">DADOS REAIS DE ESTUDO</span><h1>Seu progresso</h1><p>As porcentagens são calculadas somente a partir de tentativas registradas neste dispositivo; não representam notas previstas.</p></div><div class="stats">${metric('Tentativas',all.filter(a=>a.origin!=='reveal').length,'exercícios respondidos')}${metric('Acerto s/ ajuda',acc===null?'—':acc+'%','sobre todas as tentativas')}${metric('Dias ativos',dailies,'dias com respostas')}</div><section class="section"><div class="secthead"><h2>Domínio por matéria</h2></div><div class="card stack">${D.subjects.map(s=>{const a=accurate(s.id);const n=done(s.id);return `<div><div class="barrow"><span class="barlabel">${esc(s.short)}</span><div class="bartrack"><div class="barfill" style="width:${a??0}%;background:${s.accent}"></div></div><span class="barvalue">${a===null?'sem dados':a+'%'}</span></div><div class="tiny" style="margin-top:5px">${n} tentativa(s)</div></div>`}).join('')}</div></section><section class="section"><div class="secthead"><h2>Caderno de erros</h2></div>${weak.length?weak.map(x=>`<div class="erroritem"><strong>${esc(subj(x.subject)?.short)} · ${esc(x.topic)}</strong><p>${x.wrong} tentativa(s) com erro/ajuda/baixa confiança em ${x.total} registrada(s).</p><button class="btn ghost sm" data-act="retest-topic" data-sub="${x.subject}" data-topic="${attr(x.topic)}">Retestar ${icon('arrow')}</button></div>`).join(''):`<div class="empty">Os seus erros aparecerão aqui quando você começar a praticar. Não temos ainda dados para classificar dificuldades.</div>`}</section><section class="section"><h2 style="font-size:19px">Revisões recomendadas</h2><div class="card">${latestAttempts().filter(a=>a.reviewDue&&a.reviewDue<=today()).length} tentativa(s) precisam de reteste. Acerto com baixa confiança ou dica não equivale a domínio.</div><div class="actions"><button class="btn secondary sm" data-page="grades">Notas e metas P2</button><button class="btn secondary sm" data-page="prep">Exam Prep</button><button class="btn secondary sm" data-page="daily">Exercício do dia</button></div></section>${adaptiveProgress()}${reviewTimeline()}<section class="section"><h2 style="font-size:19px">Últimas atividades</h2>${all.length?all.slice(-8).reverse().map(a=>`<div class="topiccard" style="margin-top:8px"><span><strong>${esc(subj(a.subject)?.short)} · ${esc(a.topic)}</strong><span>${esc(a.date)} · ${a.origin==='reveal'?'consultou resolução':a.help?'usou ajuda':a.correct?'acertou':'errou'}</span></span><span class="badge" style="color:${a.correct&&!a.help?'var(--good)':'var(--bad)'}">${a.correct&&!a.help?'✓':'↺'}</span></div>`).join(''):`<p class="subtle">Ainda não há respostas registradas.</p>`}</section>`}
  function shiftDate(day,n){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+n);return F.dateLocal(d)}
  function dailyTeaser(){const events=calendarEvents();return `<section class="section"><div class="secthead"><h2>Exercício do dia</h2><button class="sectionlink" data-page="daily">Abrir →</button></div><div class="card">${events.length?`<span class="badge gold">${events.length} bloco(s) de estudo no Calendar importado</span><h3 style="margin-top:12px">${esc(events[0].title)}</h3><p>${esc(events[0].subject)} · ${esc(events[0].start)}–${esc(events[0].end)} · cópia local</p><button class="btn sm" data-page="daily">Iniciar exercício guiado</button>`:`<h3>${db.imports.calendar?'Sem bloco de estudo para hoje':'Importe sua agenda de estudos'}</h3><p>${db.imports.calendar?'Nenhum exercício diário será imposto sem evento de estudo.':'O Órbita só seleciona exercícios do dia após importar sua agenda pessoal.'}</p><button class="btn secondary sm" data-page="${db.imports.calendar?'daily':'settings'}">${db.imports.calendar?'Ver agenda':'Importar agenda'}</button>`}</div></section>`}
  function saveDaily(){const ev=calendarEvents(dailyDate)[chosenBlock()],ch=F.chooseDaily(ev,errorsFor(ev?.subject));if(!ev||!ch||!dailyReveal||!dailyStatus)return;const id=`${dailyDate}|${ev.start}|${ch.id}`;const item={id,day:dailyDate,event:ev.title,subject:ev.subject,challengeId:ch.id,confidence:dailyConfidence,status:dailyStatus,source:'autoavaliação',savedAt:new Date().toISOString()};db.dailyAttempts=db.dailyAttempts.filter(a=>a.id!==id);db.dailyAttempts.push(item);db.reviewLog=db.reviewLog.filter(x=>x.id!==id);db.reviewLog.push({id,subject:ev.subject,topic:ch.title,date:dailyDate,source:'autoavaliação',outcome:dailyStatus,reviewDue:shiftDate(dailyDate,dailyStatus==='independente'&&dailyConfidence>=75?3:1)});if(save())showToast('Autoavaliação salva');render()}
  function viewDaily(){const evs=calendarEvents(dailyDate),ev=evs[chosenBlock()],ch=F.chooseDaily(ev,errorsFor(ev?.subject)),prior=errorsFor(ev?.subject),doneToday=db.dailyAttempts.filter(a=>a.day===dailyDate);return `<div class="pagehead"><span class="eyebrow">ESTUDO GUIADO · CÓPIA LOCAL</span><h1>Exercício do dia</h1><p>Calendar define a matéria; erros importados do Notion orientam a revisão. Não há sincronização automática.</p></div><div class="card"><div class="row between wrap"><button class="btn secondary sm" data-act="daily-date" data-date="${shiftDate(dailyDate,-1)}">← Dia anterior</button><strong>${esc(dailyDate)}</strong><button class="btn secondary sm" data-act="daily-date" data-date="${shiftDate(dailyDate,1)}">Próximo dia →</button></div><div class="field" style="margin-top:12px"><label for="daily-date">Escolher data</label><input id="daily-date" type="date" value="${dailyDate}" /></div><p class="tiny">Agenda: ${privateBadge('calendar')}</p></div>${upcomingBlocks()}${!db.imports.calendar?`<div class="section notice">Importe o arquivo agenda_estudos_snapshot.json em Configurações para habilitar o exercício do dia. Não geramos agenda fictícia.</div><button class="btn" data-page="settings">Importar agenda</button>`:!ev?`<div class="section empty">Nenhum bloco “Estudo P2” cadastrado para ${esc(dailyDate)} no snapshot importado. Sem exercício diário neste dia.</div>`:`<div class="section stack"><div class="card"><span class="eyebrow">BLOCOS DE ESTUDO · ${esc(dailyDate)}</span>${evs.map((x,i)=>`<button class="topiccard ${chosenBlock()===i?'selected':''}" data-act="daily-block" data-value="${i}"><span>${esc(x.start)}–${esc(x.end||'')} · <strong>${esc(x.subject)}</strong> · ${esc(x.title)}</span></button>`).join('')}<p class="tiny">Escolha o bloco que deseja estudar. Títulos sem assunto correspondente não geram exercícios arbitrários.</p></div>${ch?`<div class="quizbox"><span class="badge gold">Questão autoral · ${ch.minutes} min</span><h2>${esc(ch.title)}</h2><p>${esc(ch.statement)}</p><h3 style="font-size:15px">Método sugerido — sem entregar a resposta</h3><ol class="study-steps">${ch.prompts.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="hint"><strong>Dica de preparação:</strong> ${esc(ch.hint)}</div><div class="confidence-panel"><strong>Antes de conferir: qual sua confiança?</strong><div class="chips">${[20,50,75,100].map(n=>`<button class="chip ${dailyConfidence===n?'on':''}" data-act="daily-confidence" data-value="${n}">${n}%</button>`).join('')}</div></div>${dailyReveal?`<div class="explanation"><strong>Correção comentada</strong><p>${esc(ch.solution)}</p><p><strong>Revisão recomendada:</strong> se houve erro, ajuda ou baixa confiança, retome amanhã. Se resolveu sozinho com confiança, refaça em três dias sem consultar a solução; o registro calcula essa data.</p></div><div class="confidence-panel"><strong>Como foi sua tentativa? (autoavaliação, não nota automática)</strong><div class="chips">${[['independente','Resolvi sozinho'],['com_ajuda','Precisei de ajuda'],['nao_resolvi','Não resolvi']].map(([v,t])=>`<button class="chip ${dailyStatus===v?'on':''}" data-act="daily-status" data-value="${v}">${t}</button>`).join('')}</div></div><button class="btn" data-act="daily-save" ${!dailyStatus?'disabled':''}>Registrar tentativa</button>`:`<button class="btn" data-act="daily-reveal" ${dailyConfidence===null?'disabled':''}>Conferir resolução</button>`}</div>`:`<div class="notice">Sem exercício específico para este bloco. Use a lista de exercícios da matéria, sem fingir que existe uma questão correspondente.</div>`}${prior.length?`<div class="card"><h3>Pontos do Notion para revisar</h3><p class="tiny">${privateBadge('notion')}</p>${prior.slice(0,5).map(x=>`<div class="erroritem"><strong>${esc(x.topic)}</strong><p>${esc(x.next_rule||x.evidence||'Consultar o registro original.')}</p></div>`).join('')}</div>`:`<div class="notice">${db.imports.notion?'Nenhum erro priorizado nesta matéria no snapshot.':'Importe o snapshot do Notion para associar seus erros ao exercício.'}</div>`}${doneToday.length?`<div class="card"><h3>Registros do dia</h3>${doneToday.map(x=>`<p>${esc(x.event)} · confiança ${x.confidence}% · ${esc(x.status.replaceAll('_',' '))} · autoavaliação</p>`).join('')}</div>`:''}</div>`}`}
  function viewPrep(){const s=subj(prepSubject)||D.subjects[0],qs=D.questions.filter(q=>q.subject===s.id),g=db.imports.notion?.grades?.find(g=>g.subject===s.id),errs=errorsFor(s.id),local=weakTopics().filter(x=>x.subject===s.id);return `<div class="pagehead"><span class="eyebrow">EXAM PREP · P2 / P3</span><h1>Preparação de provas</h1><p>Um treino de cada vez: recuperar teoria, tentar sem consulta, estimar confiança e corrigir pelo método.</p></div><div class="chips">${D.subjects.map(x=>`<button class="chip ${x.id===s.id?'on':''}" data-act="prep-sub" data-sub="${x.id}">${esc(x.short)}</button>`).join('')}</div><div class="card"><span class="eyebrow">${esc(s.id)} · ${esc(s.name)}</span><h3 style="margin-top:10px">Seu plano de treino</h3><p>${qs.length} questões objetivas autorais disponíveis; ${F.challenges.filter(x=>x.subject===s.id).length} exercício(s) elaborado(s) na biblioteca do exercício do dia.</p>${g?`<p>P1: ${Number.isFinite(g.p1)?g.p1.toFixed(1).replace('.',','):'não informada'} · prioridade ${esc(g.priority)} · mínimo estimado P2: ${F.p2Needed(g)===null?'indisponível':(Math.ceil(F.p2Needed(g)*100-1e-9)/100).toFixed(2).replace('.',',')}</p><p class="tiny">Importação privada; projeções não são notas oficiais.</p>`:`<p class="tiny">Importe o Notion para exibir suas notas e prioridades.</p>`}<div class="actions"><button class="btn" data-act="start-sim" data-sub="${s.id}">Simulado · ${Math.min(prepCount,rankedQuestions(s.id).length)} questões</button><button class="btn secondary" data-act="sub-quiz" data-sub="${s.id}">Treino livre</button><button class="btn ghost" data-page="grades">Metas de notas</button></div></div>${simOptions(s,qs)}${simHistory(s.id)}<section class="section"><h2>Revisar antes da prova</h2>${errs.length?errs.map(x=>`<div class="erroritem"><strong>${esc(x.topic)}</strong><p>${esc(x.observation||'')} · ${esc(x.next_rule||'')}</p></div>`).join(''):`<div class="empty">${db.imports.notion?'Sem erros priorizados no snapshot desta matéria.':'Importe o snapshot do Notion para ver seus pontos fracos.'}</div>`}${local.map(x=>`<div class="card"><strong>${esc(x.topic)}</strong><p>${x.wrong}/${x.total} tentativa(s) com erro, ajuda ou baixa confiança neste dispositivo.</p><button class="btn secondary sm" data-act="retest-topic" data-sub="${s.id}" data-topic="${attr(x.topic)}">Retestar</button></div>`).join('')}</section><div class="section card"><h3>Critério de domínio</h3><p>O simulado prioriza erros locais, dificuldades importadas e revisões vencidas. Uma resposta correta com dica, baixa confiança ou após consultar o gabarito exige reteste independente. O simulado é autoral e não substitui provas anteriores da FEI.</p></div>`}
  function viewSimResult(){if(!examMode)return viewPrep();const attempts=db.attempts.filter(x=>x.simId===examMode.id),correct=attempts.filter(x=>x.correct&&!x.help).length;return `<div class="pagehead"><span class="eyebrow">SIMULADO FINALIZADO</span><h1>Resultado do treino</h1><p>${esc(subj(examMode.subject)?.name||examMode.subject)} · ${attempts.length} tentativa(s) registradas</p></div><div class="stats">${metric('Sem ajuda',correct,`de ${attempts.length}`)}${metric('Acerto',attempts.length?percent(correct,attempts.length)+'%':'—','não é nota da FEI')}${metric('Confiança média',attempts.filter(x=>Number.isFinite(x.confidence)).length?Math.round(attempts.filter(x=>Number.isFinite(x.confidence)).reduce((v,x)=>v+x.confidence,0)/attempts.filter(x=>Number.isFinite(x.confidence)).length)+'%':'—','informada antes da correção')}</div><div class="section card"><h3>O que revisar?</h3>${attempts.filter(x=>!x.correct||x.help||x.confidence<75).map(x=>`<p>${esc(x.topic)} · ${x.help?'usou ajuda':!x.correct?'errou':'acertou com baixa confiança'}</p>`).join('')||'<p>Sem pontos fracos nesta tentativa. Faça outro simulado em outro dia para confirmar retenção.</p>'}${attempts.map(a=>{const q=D.questions.find(q=>q.id===a.qid);return q?`<details><summary>${esc(q.topic)} · ${a.correct?"Acerto":"Revisar"}</summary>${correction(q,a.choice)}</details>`:""}).join('')}<button class="btn" data-act="exit-sim">Voltar ao Exam Prep</button></div>`}
  function viewGrades(){const grades=db.imports.notion?.grades||[];return `<div class="pagehead"><span class="eyebrow">NOTAS E METAS</span><h1>Planejamento para P2</h1><p>Valores importados do Notion, não sincronizados. A nota mínima é indicador de risco, não meta de domínio.</p></div><div class="notice">${privateBadge('notion')} · Projeções não são notas oficiais. Para aprovação, confirme os critérios da sua turma.</div>${grades.length?`<div class="stack">${grades.map(g=>{const n=F.p2Needed(g);return `<div class="card"><div class="row between wrap"><h3>${esc(g.subject)}</h3><span class="badge ${g.priority==='Alta'?'gold':''}">${esc(g.priority||'A definir')}</span></div><p>P1: <strong>${Number.isFinite(g.p1)?g.p1.toFixed(1).replace('.',','):'não registrada'}</strong> · P2 mínima estimada: <strong>${n===null?'indisponível':(Math.ceil(n*100-1e-9)/100).toFixed(2).replace('.',',')}</strong></p><p class="tiny">${esc(g.formula||'Critério pendente')}</p>${g.note?`<div class="notice">${esc(g.note)}</div>`:''}${g.subject==='MEF120'?`<p class="tiny">Estimativa de P2 supõe T1=10 e T2=10; apenas T2=10 consta como nota registrada.</p>`:''}</div>`}).join('')}</div>`:`<div class="empty">Importe o snapshot do Notion em Configurações para visualizar notas e prioridades.</div>`}<div class="section"><button class="btn secondary" data-page="settings">Atualizar dados locais</button></div>`}
  function viewPlan(){let exams=examsUpcoming();return `<div class="row" style="margin-bottom:18px"><button class="backbtn" data-page="home">${icon('back')}</button><span class="eyebrow">ORGANIZE SUA P2</span></div><div class="pagehead"><h1>Plano de avaliações</h1><p>Cadastre suas provas e entregas. Datas não foram presumidas; só serão exibidas após você adicioná-las.</p></div><div class="actions"><button class="btn" data-act="new-exam">${icon('clock')} Nova avaliação</button><button class="btn secondary" data-page="grades">Notas e metas P2</button><button class="btn secondary" data-page="prep">Exam Prep</button></div><div class="section stack">${db.exams.length?db.exams.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="card"><div class="row between"><span class="eyebrow">${esc(subj(e.subject)?.short)}</span><span class="badge ${daysUntil(e.date)>=0?'gold':''}">${daysUntil(e.date)<0?'Concluída/passada':daysUntil(e.date)+' dia(s)'}</span></div><h3 style="margin-top:12px">${esc(e.title)}${e.type?` · ${esc({exam:"Prova",lab:"Laboratório",activity:"Atividade avaliativa",mock:"Simulado"}[e.type]||e.type)}`:""}</h3><p>${esc(e.date)} · ${esc(e.topics||'Assuntos a definir')}</p><div class="row wrap"><button class="btn secondary sm" data-act="sub-quiz" data-sub="${e.subject}">Praticar matéria</button><button class="btn ghost sm" data-act="delete-exam" data-id="${attr(e.id)}">Remover</button></div></div>`).join(''):`<div class="empty">Nenhuma avaliação cadastrada. Use “Nova avaliação” para registrar a próxima prova da FEI.</div>`}</div><div class="section notice">O planejamento usa a data cadastrada e os erros nos exercícios; não acessa automaticamente seu Google Calendar nesta versão.</div>`}
  function correction(q,choice){
    const answer=q.choices?.[q.answer];
    return `<div class="worked-solution"><h4>Gabarito</h4><p>${esc(answer||q.solution)}</p><h4>Resolução comentada</h4><p>${esc(q.explanation||q.solution)}</p>${choice!=null&&choice!==q.answer?`<p><strong>Sua resposta:</strong> ${esc(q.choices?.[choice])}. Compare com o raciocínio acima e registre a hipótese ou etapa em que houve divergência.</p>`:''}<p><strong>Revisão:</strong> refaça sem consultar a resolução; confira hipóteses, sinais e unidades nas relações apresentadas. Em questões conceituais, não há substituição numérica.</p></div>`;
  }
  function viewSettings(){return `<div class="pagehead"><span class="eyebrow">CONTROLE E PRIVACIDADE</span><h1>Configurações</h1><p>Aplicativo pessoal, sem conta obrigatória ou API paga. Seus dados permanecem armazenados neste navegador.</p></div><div class="stack"><div class="card"><h3>Instalar no iPhone</h3><p>Depois de publicar esta pasta em um site HTTPS, abra o endereço no Safari. Toque em Compartilhar → Adicionar à Tela de Início (ou “Abrir como App da Web”) e confirme. O PWA pode funcionar offline após o primeiro carregamento.</p><div class="notice">Abrir um arquivo HTML pelo app Arquivos não equivale a instalar um PWA; o domínio publicado é necessário.</div></div><div class="card"><h3>Seu backup</h3><p>Exportar um arquivo JSON é recomendado antes de trocar de celular ou limpar os dados do navegador.</p><div class="actions"><button class="btn sm" data-act="export">${icon('download')} Exportar backup</button><label class="btn secondary sm" for="backupimport">${icon('upload')} Importar backup</label><input style="display:none" id="backupimport" type="file" accept="application/json,.json"/></div></div><div class="card"><h3>Importar pacote pessoal único</h3><p>Selecione o pacote JSON unificado preparado a partir dos quatro arquivos. A importação é local, incremental e preserva tentativas, notas, revisões e backups. Reimportar atualiza registros sem duplicá-los. Não é sincronização automática.</p><label class="btn secondary sm" for="personal-package">Importar pacote pessoal</label><input class="hide" type="file" id="personal-package" accept=".json,application/json"/><p class="tiny">${db.imports.calendar?.complete===false?'Agenda parcial: somente os blocos recebidos estão disponíveis.':''} ${db.imports.calendar?.study_events?.length||0} eventos locais · ${db.imports.notion?.error_records?.length||0} dificuldades · ${db.imports.drive?.verified_documents?.length||0} materiais · ${db.exams.length} avaliações cadastradas. ${db.imports.notion?.references?.length||0} referências de bases do Notion. Nenhuma data estimada é cadastrada como prova.</p>${(db.imports.notion?.references||[]).map(x=>`<p><a target="_blank" rel="noopener noreferrer" href="${attr(x.url)}">${esc(x.title)}</a></p>`).join('')}</div><div class="card"><h3>Conectar seu planejamento (importação privada)</h3><p>Importe JSONs do seu pacote pessoal (agenda também aceita ICS sem recorrência/TZID; Notion aceita CSV de erros): agenda_estudos_snapshot.json, notion_estudos_snapshot.json e fontes_drive.json. São cópias locais, <strong>não uma conexão automática</strong>. Dados ficam apenas neste navegador e entram no backup.</p><div class="stack">${[['calendar','Agenda do Google Calendar'],['notion','Erros e notas do Notion'],['drive','Links privados do Drive']].map(([key,label])=>`<div class="importrow"><div><strong>${label}</strong><small>${privateBadge(key)}</small></div><label class="btn secondary sm" for="import-${key}">Importar</label><input class="hide" type="file" id="import-${key}" accept="${key==='calendar'?'.json,.ics':key==='notion'?'.json,.csv':'.json'}"/></div>`).join('')}</div><p class="tiny">Não publique esses JSONs na hospedagem ou em repositórios públicos. Para atualizá-los, exporte novas cópias autorizadas.</p></div><div class="card"><h3>Atualização do aplicativo</h3><p>Uma versão nova fica aguardando até você escolher atualizar. Exporte seu backup e termine o simulado antes de trocar de versão.</p><div class="actions"><button class="btn secondary sm" data-act="check-update">Verificar atualização</button><button class="btn secondary sm" data-act="activate-update">Aplicar atualização disponível</button></div><p class="tiny" id="pwa-status">Atualizações não apagam o progresso.</p></div><div class="card" id="connections-panel"><h3>Conectar minhas contas</h3><p>Verificando disponibilidade do servidor seguro…</p></div><div class="card"><h3>Catálogo e recomendações</h3><p>${window.ORBITA_CATALOG?.current?.items.length||D.feed.length} atividades disponíveis. Histórico de exibição e conclusão permanece neste dispositivo.</p><button class="btn secondary sm" data-act="catalog-refresh">Atualizar catálogo</button><button class="btn secondary sm" data-page="videos">Biblioteca de vídeos</button><button class="btn ghost sm" data-act="reset-video-failures">Tentar novamente vídeos indisponíveis</button></div><div class="card"><h3>Conexões automáticas</h3><p>O estado real das contas aparece em “Conectar minhas contas”. Importar um pacote não autoriza acesso às contas. A conexão persistente exige servidor seguro disponível na hospedagem existente e consentimento Google/Notion; senhas e tokens não devem ser enviados por mensagem.</p></div><div class="card"><h3>Inteligência artificial</h3><p>Os recursos atuais utilizam questões originais preparadas e regras locais de revisão. Não existe uma API generativa conectada. Futuramente poderá ser integrado um modelo gratuito dentro dos limites da plataforma, com proteção de chaves no servidor.</p><span class="badge">Modo offline · Sem cobrança</span></div><div class="card"><h3>Materiais e fontes</h3><p>Os atalhos são adicionados privadamente pelo arquivo importado e apontam para pastas e documentos no Google Drive. Esta versão ainda não extrai automaticamente todos os PDFs, gabaritos e arquivos de outras conversas.</p><button class="btn secondary sm" data-page="study">Ver materiais das matérias</button></div><div class="card"><h3>Limpar histórico</h3><p>Esta ação exclui o progresso, as notas e as provas deste dispositivo. Exporte antes se quiser guardar seus registros.</p><button class="btn danger sm" data-act="reset-data">Apagar dados locais</button></div><div class="card"><h3>Sobre o Órbita</h3><p>App autoral pessoal, inspirado em funções educacionais de mercado. Não é afiliado ao Astra AI nem à FEI. As questões são de treinamento e devem ser verificadas com o professor e o material original em caso de divergência.</p></div></div>`}
  function modalHTML(){if(modal.type==='exam')return `<div class="modalmask"><div class="modal"><div class="modalhead"><h2>Nova avaliação</h2><button class="iconbtn" data-act="close-modal" aria-label="Fechar">${icon('close')}</button></div><p>Cadastre a avaliação real, sem estimativas inventadas.</p><form id="examform" class="stack"><div class="field"><label>Matéria</label><select name="subject" required>${D.subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Nome da avaliação</label><input name="title" placeholder="Ex.: P2" maxlength="90" required/></div><div class="field"><label>Data</label><input name="date" type="date" required/></div><div class="field"><label>Assuntos</label><textarea name="topics" placeholder="Ex.: condução radial e aletas" maxlength="600"></textarea></div><div class="modalfoot"><button type="button" class="btn secondary" data-act="close-modal">Cancelar</button><button type="submit" class="btn">Salvar</button></div></form></div></div>`;
  if(modal.type==='note'){let key=modal.subject+'|'+modal.topic;return `<div class="modalmask"><div class="modal"><div class="modalhead"><h2>Anotação</h2><button class="iconbtn" data-act="close-modal">${icon('close')}</button></div><p>${esc(modal.topic)} · ${modal.subject}</p><form id="noteform" class="stack"><div class="field"><label>Minha anotação / ponto de dúvida</label><textarea name="content" rows="7" maxlength="10000" placeholder="Descreva o que errou ou o que precisa revisar...">${esc(db.notes[key]||'')}</textarea></div><div class="modalfoot"><button type="button" class="btn secondary" data-act="close-modal">Cancelar</button><button class="btn" type="submit">Guardar nota</button></div></form></div></div>`}
  if(modal.type==='link')return `<div class="modalmask"><div class="modal"><div class="modalhead"><h2>Novo link de estudo</h2><button class="iconbtn" data-act="close-modal">${icon('close')}</button></div><p>Material adicional da matéria ${esc(modal.subject)}</p><form id="linkform" class="stack"><div class="field"><label>Título do material</label><input name="title" maxlength="140" required/></div><div class="field"><label>Endereço HTTPS</label><input name="url" type="url" placeholder="https://..." required/></div><div class="modalfoot"><button type="button" class="btn secondary" data-act="close-modal">Cancelar</button><button class="btn" type="submit">Salvar link</button></div></form></div></div>`;
  if(modal.type==='session')return `<div class="modalmask"><div class="modal"><div class="modalhead"><h2>Uma sessão no seu ritmo</h2><button class="iconbtn" data-act="close-modal">${icon('close')}</button></div><p>O objetivo é aprender, não consumir o feed sem perceber o tempo.</p><div class="chips">${['5','15','30'].map(x=>`<button class="chip ${db.settings.duration===x?'on':''}" data-act="set-duration" data-value="${x}">${x} min</button>`).join('')}</div><div class="modalfoot"><button class="btn secondary" data-act="stop-session">Encerrar</button><button class="btn" data-act="start-session">Iniciar sessão</button></div></div></div>`;
  if(modal.type==='summary')return `<div class="modalmask"><div class="modal"><div class="modalhead"><h2>Sessão concluída</h2><button class="iconbtn" data-act="close-modal">${icon('close')}</button></div><p>Você pode encerrar agora. Retomar é uma escolha sua.</p><div class="stats">${metric('Conteúdos vistos',db.feedViewed.length,'únicos no dispositivo')}${metric('Exercícios hoje',db.attempts.filter(a=>a.date===today()).length,'tentativas')}${metric('Itens salvos',db.savedFeed.length,'revisar depois')}</div><div class="modalfoot"><button class="btn secondary" data-act="close-modal">Rever esta sessão</button><button class="btn secondary" data-act="new-feed-session">Gerar outra sessão</button><button class="btn" data-page="home">Voltar ao início</button></div></div></div>`;
  return ''}
  function initFeedTimer(){if(!feedTimer)return;if(tick)return;tick=setInterval(()=>{if(page!=='feed'){stopTimer();return;}const left=Math.max(0,Math.ceil((feedTimer.end-Date.now())/1000));const node=document.getElementById('timer-info');if(node)node.textContent=`Sessão consciente · ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')} restantes`;if(left<=0){feedTimer=null;stopTimer();modal={type:'summary'};render()}},1000)}
  function stopTimer(){if(tick){clearInterval(tick);tick=null}};
  function download(name,txt,mime){const blob=new Blob([txt],{type:mime});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
  function viewVideos(){const videos=D.feed.filter(x=>x.format==='video'),f=videos.find(x=>x.id===selectedVideo);return `<div class="pagehead"><h1>Biblioteca de vídeos</h1><p>${videos.length} vídeos de fontes acadêmicas. Metadados conferidos na fonte oficial; reprodução e duração exata não validadas nesta rede. Aulas longas ficam disponíveis aqui mesmo quando não cabem na sessão.</p></div>${f?`<div class="card"><h2>${esc(f.title)}</h2>${videoCard(f)}<button class="btn secondary" data-act="close-video">Voltar à lista</button></div>`:videos.map(x=>`<button class="topiccard" data-act="open-video" data-id="${x.id}"><span><strong>${esc(x.title)}</strong><span>${esc(x.subject)} · inglês · cerca de ${Math.ceil(x.durationSeconds/60)} min (estimativa)</span></span></button>`).join('')}`}
  function adaptiveProgress(){if(!window.ORBITA_CATALOG?.current)return '';const items=window.ORBITA_CATALOG.current.items,concepts=[...new Map(items.map(x=>[x.subject+'|'+x.concept,x])).values()],mastered=concepts.filter(x=>window.ORBITA_RECOMMEND.evidence(db,x.concept,x.subject,Date.now()).mastered);return `<section class="section"><h2>Aprendizagem no feed</h2><div class="stats">${metric('Exibidos',new Set(db.contentEvents.filter(e=>e.kind==='shown').map(e=>e.contentId)).size,'conteúdos únicos')}${metric('Concluídos',new Set(db.contentEvents.filter(e=>e.kind==='completed').map(e=>e.contentId)).size,'não equivale a domínio')}${metric('Retenção evidenciada',mastered.length,'acertos confiantes em dias distintos')}</div><p class="tiny">Assistir, ler ou concluir uma atividade não gera domínio automaticamente. O indicador usa respostas independentes em pelo menos dois dias.</p></section>`}
  function contentEvent(f,kind){if(kind==='completed'&&db.contentEvents.some(e=>e.contentId===f.id&&e.kind==='completed'&&Date.now()-e.at<6*3600000))return;db.contentEvents.push({contentId:f.id,subject:f.subject,concept:f.concept||f.topic,format:f.format||f.type,kind,at:Date.now(),reason:adaptivePlan?.queue.find(x=>x.id===f.id)?.reason||'Ação direta',catalogVersion:window.ORBITA_CATALOG?.current?.version||'legado'});if(db.contentEvents.length>10000)db.contentEvents=db.contentEvents.slice(-10000);save()}
  function videoCard(f){return `<div class="notice">${esc(f.source?.title||'Vídeo educacional')} · metadados conferidos na fonte; reprodução atual não validada · duração estimada ${Math.ceil((f.durationSeconds||0)/60)} min</div><div id="video-host"><p>O vídeo é externo e precisa de internet. Ao carregar, seu dispositivo se conecta ao YouTube.</p><button class="btn" data-act="video-load" data-id="${f.id}">Carregar vídeo</button></div><button class="btn ghost" data-act="video-unavailable" data-id="${f.id}">Vídeo indisponível: usar alternativas</button>`}
  function systemBanner(){return (storageIssue||storageConflict)?`<div class="notice" role="alert">${esc(storageIssue||'Outra aba alterou os dados. Exporte suas alterações desta aba e recarregue para evitar sobrescrever o progresso.')}<div class="actions"><button class="btn sm" data-act="export">Exportar progresso desta aba</button><button class="btn secondary sm" data-act="raw-export">Exportar dados originais</button><button class="btn secondary sm" data-act="reload-app">Recarregar</button></div></div>`:''}
  function resumeCard(){return `<div class="card section"><h3>Simulado em andamento</h3><p>${esc(db.activeSim.subject)} · ${esc(db.activeSim.stage||'P2')} · questão ${db.activeSim.index+1} de ${db.activeSim.ids.length}. Respostas anteriores preservadas.</p><div class="actions"><button class="btn" data-act="resume-sim">Retomar simulado</button><button class="btn ghost" data-act="discard-sim">Descartar simulado</button></div></div>`}
  function simOptions(s,qs){const topics=[...new Set(qs.map(q=>q.topic))];return `${db.activeSim?resumeCard():''}<div class="card section"><h3>Configure seu simulado</h3><div class="formrow"><div class="field"><label for="prep-stage">Avaliação</label><select id="prep-stage">${['P2','P3'].map(x=>`<option ${prepStage===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="prep-topic">Conteúdo</label><select id="prep-topic"><option value="all">Todos os conteúdos</option>${topics.map(t=>`<option value="${attr(t)}" ${prepTopic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="prep-count">Quantidade de questões</label><select id="prep-count">${[1,3,5,10].map(n=>`<option value="${n}" ${prepCount===n?'selected':''}>Até ${n}</option>`).join('')}</select></div></div><p class="tiny">${rankedQuestions(s.id).length} questão(ões) no conteúdo escolhido. A sequência prioriza erros ativos e revisões. P2/P3 identifica seu objetivo; não inventa pesos ou notas oficiais.</p></div>`}
  function simHistory(sub){const list=db.simHistory.filter(h=>h.subject===sub).slice(-10).reverse();return `<section class="section"><h2>Histórico de simulados</h2>${list.length?list.map(h=>`<div class="topiccard"><span><strong>${esc(h.stage||'P2')} · ${esc(h.topic==='all'?'Todos os conteúdos':h.topic||'Todos')}</strong><span>${esc(h.date)} · ${h.correct}/${h.total} acertos sem ajuda</span></span></div>`).join(''):'<div class="empty">Nenhum simulado concluído nesta disciplina.</div>'}</section>`}
  function upcomingBlocks(){const blocks=F.nextBlocks(db.imports.calendar,D.subjects);return blocks.length?`<div class="section card"><h3>Próximos blocos de estudo</h3>${blocks.map(e=>`<button class="topiccard" data-act="daily-jump" data-date="${e.date}" data-start="${e.start}" data-sub="${e.subject}"><span><strong>${esc(e.date)} · ${esc(e.start)} · ${esc(e.subject)}</strong><span>${esc(e.title)}${e.type?` · ${esc({exam:"Prova",lab:"Laboratório",activity:"Atividade avaliativa",mock:"Simulado"}[e.type]||e.type)}`:""}</span></span></button>`).join('')}<p class="tiny">Horário do dispositivo · cópia importada. Aulas sem identificação de estudo são ignoradas.</p></div>`:''}
  function reviewTimeline(){const due=latestAttempts().filter(a=>a.reviewDue<=today());return `<section class="section"><h2>Fila de revisão</h2>${due.length?due.map(a=>`<button class="topiccard" data-act="retest-question" data-id="${attr(a.qid)}"><span><strong>${esc(a.subject)} · ${esc(a.topic)}</strong><span>Revisar desde ${esc(a.reviewDue)} · ${a.interval||1} dia(s) de intervalo</span></span></button>`).join(''):'<div class="empty">Nenhuma revisão de questão vencida.</div>'}<h3>Histórico de revisões</h3>${db.reviewLog.slice(-15).reverse().map(a=>`<div class="topiccard"><span><strong>${esc(a.subject)} · ${esc(a.topic)}</strong><span>${esc(a.date)} · ${esc(a.source)} · ${esc(a.outcome)} · próxima: ${esc(a.reviewDue||'—')}</span></span></div>`).join('')||'<p class="tiny">As próximas tentativas e autoavaliações formarão este histórico.</p>'}</section>`}
  function flashPool(){const last=new Map(F.latest(db.reviewed).map(r=>[r.id,r]));return D.flashcards.filter(f=>flashFilter==='all'||f.subject===flashFilter).slice().sort((a,b)=>(last.get(a.id)?.reviewDue||'0000').localeCompare(last.get(b.id)?.reviewDue||'0000'))}
  function errorEditor(q){const a=db.attempts.at(-1);if(!a||a.qid!==q.id||a.origin==='reveal'||a.correct&&!a.help&&a.confidence>=75)return '';return `<div class="field"><label for="error-kind">Onde surgiu a dificuldade?</label><select id="error-kind" data-id="${attr(a.id)}"><option value="">Não classificado</option>${['conceito','método','unidades','cálculo','interpretação'].map(t=>`<option ${a.errorType===t?'selected':''}>${t}</option>`).join('')}</select></div><p class="tiny">Descreva o raciocínio no caderno de anotações da matéria; esta classificação acompanha seu backup.</p>`}
  function visualDiagram(f){if(f.subject==='MED120')return `<svg class="lesson-svg" viewBox="0 0 300 130" role="img" aria-label="Massa oscilando em uma mola, modelo de um grau de liberdade"><path d="M20 30v70m0-35h15l10-15 15 30 15-30 15 30 15-15h25" fill="none" stroke="currentColor" stroke-width="3"/><g class="oscillating"><rect x="130" y="35" width="55" height="60" rx="8" fill="#f2bf61"/><text x="157" y="72" text-anchor="middle" fill="#111">m</text></g><text x="220" y="50" fill="currentColor">ωn = √(k/m)</text><text x="215" y="85" fill="currentColor">x(t) →</text></svg>`;if(['MEE120','MEI150'].includes(f.subject))return `<svg class="lesson-svg" viewBox="0 0 300 130" role="img" aria-label="Fluxo de calor do lado quente para o frio através de uma parede"><rect x="120" y="15" width="60" height="100" fill="#657489"/><path class="heat-arrow" d="M35 65h220m-15-12 15 12-15 12" fill="none" stroke="#f2bf61" stroke-width="5"/><text x="25" y="35" fill="#f09a96">Quente</text><text x="225" y="35" fill="#8bd4fa">Frio</text><text x="150" y="125" fill="currentColor" text-anchor="middle">Q = k A ΔT / L · parede plana</text></svg>`;if(!['MEP230','MEP140'].includes(f.subject))return `<div class="visual-method"><strong>Identificar</strong><span>↓</span><strong>Modelar</strong><span>↓</span><strong>Verificar</strong><small>Dados · hipóteses · unidades · evidências</small></div>`;return `<svg class="lesson-svg" viewBox="0 0 300 130" role="img" aria-label="Diagrama de equilíbrio: viga apoiada e força vertical"><path d="M30 75h240M50 75l-15 25h30zM250 75l-15 25h30zM150 10v45m-10-12 10 12 10-12" stroke="currentColor" stroke-width="3" fill="none"/><text x="165" y="32" fill="currentColor">F</text><text x="150" y="120" fill="currentColor" text-anchor="middle">DCL → equilíbrio → modelo → resultado</text></svg>`}
  function handleAction(el){const a=el.dataset.act, sub=el.dataset.sub,topic=el.dataset.topic;switch(a){
    case 'open-sub':navigate('subject',{subject:sub});break;
    case 'prep-sub':prepSubject=sub;prepTopic='all';render();break;
    case 'start-sim':{if(db.activeSim){showToast('Retome ou descarte o simulado em andamento antes de iniciar outro.');break;}const ids=rankedQuestions(sub).slice(0,prepCount).map(q=>q.id);if(!ids.length){showToast('Não há questões para esse conteúdo.');break;}prepSubject=sub;selectedQuiz=sub;resetQuiz();quizIndex=0;examMode={id:String(Date.now()),ids,subject:sub,topic:prepTopic,stage:prepStage,limit:ids.length,startIndex:db.attempts.length};save();navigate('quiz');break;}
    case 'resume-sim':{if(window.ORBITA_CATALOG?.status==='loading'){showToast('Aguarde o catálogo antes de retomar.');break;}const a=db.activeSim;if(!a)break;examMode={...a};quizIndex=a.index;picked=a.picked??null;assessed=!!a.assessed;hinted=!!a.hinted;reveal=!!a.reveal;confidence=a.confidence??null;selectedQuiz=a.subject;navigate('quiz');break;}
    case 'discard-sim':if(confirm('Descartar o simulado em andamento? As respostas já registradas serão preservadas.')){db.activeSim=null;examMode=null;save();render();}break;
    case 'exit-sim':examMode=null;navigate('prep');break;
    case 'confidence':confidence=Number(el.dataset.value);save();render();break;
    case 'daily-date':dailyDate=el.dataset.date;dailyBlock=-1;dailyReveal=false;dailyConfidence=null;dailyStatus=null;render();break;
    case 'daily-jump':dailyDate=el.dataset.date;dailyBlock=Math.max(0,calendarEvents(dailyDate).findIndex(e=>e.start===el.dataset.start&&e.subject===sub));dailyReveal=false;dailyConfidence=null;dailyStatus=null;navigate('daily');break;
    case 'retest-question':{const q=D.questions.find(q=>q.id===el.dataset.id);if(!q)break;resetQuiz();examMode=null;selectedQuiz=q.subject;focusForStudy=q.topic;quizIndex=qpool().findIndex(x=>x.id===q.id);navigate('quiz');break;}
    case 'daily-block':dailyBlock=Number(el.dataset.value);dailyReveal=false;dailyConfidence=null;dailyStatus=null;render();break;
    case 'daily-confidence':dailyConfidence=Number(el.dataset.value);render();break;
    case 'daily-reveal':if(dailyConfidence===null){showToast('Registre sua confiança antes da correção');break;}dailyReveal=true;render();break;
    case 'daily-status':dailyStatus=el.dataset.value;render();break;
    case 'daily-save':saveDaily();break;
    case 'daily-challenge':dailyDate=el.dataset.date||today();dailyReveal=false;dailyConfidence=null;dailyStatus=null;navigate('daily');break;
    case 'open-topic':selectedTopic=topic;render();break;
    case 'clear-topic':selectedTopic=null;render();break;
    case 'sub-tab':selectedSubTab=el.dataset.tab;selectedTopic=null;render();break;
    case 'sub-quiz':examMode=null;focusForStudy=null;selectedQuiz=sub;quizIndex=0;picked=null;assessed=false;hinted=false;reveal=false;confidence=null;navigate('quiz');break;
    case 'topic-quiz':case 'retest-topic':{examMode=null;focusForStudy=topic;selectedQuiz=sub;const found=D.questions.some(q=>q.subject===sub&&q.topic===topic);if(!found){focusForStudy=null;showToast('Sem exercício específico; abrindo matéria')}quizIndex=0;picked=null;assessed=false;hinted=false;reveal=false;confidence=null;navigate('quiz');break;}
    case 'topic-note':modal={type:'note',subject:sub,topic};render();break;
    case 'new-link':modal={type:'link',subject:sub};render();break;
    case 'new-exam':modal={type:'exam'};render();break;
    case 'close-modal':modal=null;render();break;
    case 'delete-exam':db.exams=db.exams.filter(x=>x.id!==el.dataset.id);save();render();break;
    case 'quiz-filter':examMode=null;focusForStudy=null;selectedQuiz=sub;quizIndex=0;picked=null;assessed=false;hinted=false;reveal=false;confidence=null;render();break;
    case 'pick':pickQuiz(+el.dataset.choice);break;
    case 'assess':assessQuiz();break;
    case 'hint':hinted=true;save();render();break;
    case 'reveal':{if(assessed||reveal)break;const q=qpool()[quizIndex%qpool().length];reveal=true;record(q,null,true,'reveal',confidence);render();break;}
    case 'next-quiz':nextQuiz();break;
    case 'feed-filter':feedFilter=sub;feedIndex=0;invalidateFeed();resetFeed();render();break;
    case 'feed-reset':resetFeed();feedFilter='all';feedSavedOnly=false;feedIndex=0;invalidateFeed();render();break;
    case 'feed-save-filter':feedSavedOnly=!feedSavedOnly;feedIndex=0;invalidateFeed();resetFeed();render();break;
    case 'save-feed':{const id=el.dataset.id;db.savedFeed=db.savedFeed.includes(id)?db.savedFeed.filter(v=>v!==id):[...db.savedFeed,id];if(feedSavedOnly){feedIndex=0;resetFeed();}save();render();break;}
    case 'next-feed':nextFeed(1);break;
    case 'prev-feed':nextFeed(-1);break;
    case 'complete-content':{const f=[...D.feed,...db.privateCards].find(x=>x.id===el.dataset.id);if(f){contentEvent(f,'completed');showToast('Atividade concluída. Domínio depende de reteste independente.')}break;}
    case 'catalog-refresh':window.ORBITA_CATALOG?.refresh().then(()=>showToast('Catálogo atualizado ou cópia offline preservada'));break;
    case 'open-video':selectedVideo=el.dataset.id;navigate('videos');break;
    case 'close-video':selectedVideo=null;render();break;
    case 'reset-video-failures':db.unavailableContent=[];save();invalidateFeed();showToast('Vídeos liberados para nova tentativa; isso não confirma disponibilidade.');break;
    case 'video-unavailable':{db.unavailableContent.push(el.dataset.id);save();invalidateFeed();feedIndex=0;resetFeed();render();showToast('Vídeo removido das recomendações deste dispositivo');break;}
    case 'video-load':{if(navigator.onLine===false){showToast('Vídeos exigem internet. Use uma atividade local.');break;}const f=D.feed.find(x=>x.id===el.dataset.id);const host=document.getElementById('video-host');if(f&&host){host.innerHTML=`<iframe title="Vídeo educacional" src="https://www.youtube-nocookie.com/embed/${f.youtubeId}" allow="encrypted-media; picture-in-picture" allowfullscreen loading="lazy"></iframe>`}break;}
    case 'feed-confidence':feedConfidence=Number(el.dataset.value);render();break;
    case 'feed-answer':{if(feedAssessed||feedConfidence===null)return;feedPick=+el.dataset.choice;feedAssessed=true;const f=chooseFeed()[feedIndex%chooseFeed().length];const q=D.questions.find(x=>x.id===f.id)||D.questions.find(x=>x.subject===f.subject&&x.topic===f.topic);if(q){record(q,feedPick,false,'feed',feedConfidence);db.attempts.at(-1).feedId=f.id;contentEvent(f,'answered');contentEvent(f,'completed');save();}render();break;}
    case 'feed-study':navigate('subject',{subject:sub,topic});break;
    case 'session-options':modal={type:'session'};render();break;
    case 'set-duration':db.settings.duration=el.dataset.value;save();render();break;
    case 'new-feed-session':invalidateFeed();feedIndex=0;resetFeed();feedTimer={end:Date.now()+Number(db.settings.duration)*60000,startIndex:db.attempts.length};modal=null;render();break;
    case 'start-session':invalidateFeed();feedIndex=0;resetFeed();feedTimer={end:Date.now()+Number(db.settings.duration)*60000,startIndex:db.attempts.length};modal=null;render();break;
    case 'end-session':feedTimer=null;stopTimer();modal={type:'summary'};render();break;
    case 'stop-session':feedTimer=null;stopTimer();modal=null;render();break;
    case 'flash-filter':flashFilter=sub;flashIndex=0;flashFlipped=false;render();break;
    case 'flip-flash':flashFlipped=!flashFlipped;render();break;
    case 'mark-flash':{if(!flashFlipped)break;const list=flashPool(),f=list[flashIndex%list.length];if(!f)break;const known=el.dataset.known==='yes',prev=F.latest(db.reviewed).find(r=>r.id===f.id);db.reviewed.push({id:f.id,known,date:today(),timestamp:new Date().toISOString(),...F.schedule(prev,known,false,known?100:20,today())});save();flashIndex=0;flashFlipped=false;render();break;}
    case 'export':download(`orbita-backup-${today()}.json`,JSON.stringify({app:'orbita-estudos',version:1,exportedAt:new Date().toISOString(),data:db},null,2),'application/json');showToast('Backup exportado');break;
    case 'check-update':checkUpdate();break;
    case 'activate-update':activateUpdate();break;
    case 'raw-export':try{download('orbita-dados-originais.json',localStorage.getItem(KEY)||'{}','application/json')}catch(e){showToast('Armazenamento inacessível')}break;
    case 'reload-app':window.location.reload();break;
    case 'reset-data':if(confirm('Apagar definitivamente notas, exercícios, provas e conteúdo salvo neste navegador?')){const empty=clone(base);if(writeState(empty,true)){db=empty;examMode=null;storageIssue='';storageConflict=false;invalidateFeed();navigate('home');showToast('Dados locais apagados')}}break;
    default:break;
  }}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-act],[data-page]');if(!el)return;if(el.dataset.page){e.preventDefault();modal=null;if(el.dataset.page==='quiz'&&page!=='quiz'){resetQuiz();selectedQuiz='all';quizIndex=0;}navigate(el.dataset.page);return}if(el.dataset.act){e.preventDefault();handleAction(el)}});
  document.addEventListener('submit',e=>{const f=e.target;if(!['examform','noteform','linkform'].includes(f.id))return;e.preventDefault();const data=new FormData(f);if(f.id==='examform'){const title=String(data.get('title')||'').trim(),date=String(data.get('date')||'');if(!title||!F.date(date))return;db.exams.push({id:String(Date.now()),subject:String(data.get('subject')),title,date,topics:String(data.get('topics')||'')});showToast('Avaliação cadastrada');}
    else if(f.id==='noteform'){db.notes[modal.subject+'|'+modal.topic]=String(data.get('content')||'').trim();showToast('Anotação salva')}
    else if(f.id==='linkform'){const url=String(data.get('url')||'');if(!F.https(url)){showToast('Use um endereço HTTPS');return}db.customLinks.push({subject:modal.subject,title:String(data.get('title')),url});showToast('Material registrado')}
    save();modal=null;render()});
  document.addEventListener('change',async e=>{
    const id=e.target.id||'';
    if(id==='prep-topic'){prepTopic=e.target.value;render();return}
    if(id==='prep-count'){prepCount=Number(e.target.value);render();return}
    if(id==='prep-stage'){prepStage=e.target.value;return}
    if(id==='error-kind'){const a=db.attempts.find(a=>a.id===e.target.dataset.id);if(a){a.errorType=e.target.value;save()}return}
    if(id==='personal-package'){
      const file=e.target.files?.[0];if(!file)return;
      try{if(file.size>5*1024*1024)throw Error('Pacote acima de 5 MB');
        const data=F.normalizePersonal(JSON.parse(await file.text()),D.subjects);
        const candidate=F.mergePersonal(db,data);if(!writeState(candidate))return;db=candidate;
        dailyBlock=-1;dailyReveal=false;dailyConfidence=null;dailyStatus=null;invalidateFeed();feedIndex=0;resetFeed();render();
        showToast('Pacote mesclado sem apagar progresso. '+data.rejected.length+' registro(s) recusado(s).');
      }catch(err){showToast('Pacote não importado: '+err.message)}return;
    }
    if(id.startsWith('import-')){
      const key=id.slice(7),file=e.target.files?.[0];if(!file||!['calendar','notion','drive'].includes(key))return;
      try{if(file.size>1024*1024)throw Error('Arquivo acima de 1 MB');const text=await file.text();
        const j=key==='calendar'&&/\.ics$/i.test(file.name||'')?F.parseICS(text,D.subjects):key==='notion'&&/\.csv$/i.test(file.name||'')?{...F.parseNotionCSV(text),grades:db.imports.notion?.grades||[]}:JSON.parse(text);
        if(!({calendar:F.validCalendar,notion:F.validNotion,drive:F.validDrive})[key](j))throw Error('Estrutura incompatível');
        const candidate={...db,imports:{...db.imports,[key]:F.mergeSnapshot(key,db.imports[key],j)}};if(!writeState(candidate))return;db=candidate;
        if(key==='calendar'){dailyBlock=-1;dailyReveal=false;dailyConfidence=null;dailyStatus=null;}invalidateFeed();feedIndex=0;resetFeed();render();showToast('Cópia de '+key+' importada neste dispositivo')
      }catch(err){showToast('Não importado: '+err.message)}return;
    }
    if(id==='backupimport'){
      const file=e.target.files?.[0];if(!file)return;
      try{if(file.size>5*1024*1024)throw Error('Arquivo acima de 5 MB');const j=JSON.parse(await file.text());
        if(j.app!=='orbita-estudos'||j.version!==1||!F.validState(j.data))throw Error('Arquivo incompatível');
        if(!confirm('Importar esse backup e substituir os dados locais deste dispositivo?'))return;
        const candidate={...clone(base),...j.data,settings:{...base.settings,...j.data.settings},imports:{...base.imports,...j.data.imports}};
        if(candidate.activeSim&&!candidate.activeSim.ids.every(id=>D.questions.some(q=>q.id===id)))throw Error('Simulado contém questões desconhecidas');
        if(!writeState(candidate,true))return;db=candidate;examMode=null;storageIssue='';storageConflict=false;invalidateFeed();feedIndex=0;resetFeed();navigate('home');showToast('Backup importado')
      }catch(err){showToast('Backup inválido: '+err.message)}
    }
  });
  document.addEventListener('input',e=>{if(e.target.id==='daily-date'){dailyDate=e.target.value||today();dailyBlock=-1;dailyReveal=false;dailyConfidence=null;dailyStatus=null;render();return;}if(e.target.dataset.simParam){window.ORBITA_SIMS.update(e.target.closest('[data-sim]'));return;}if(e.target.dataset.act!=='sim-range')return;let m=document.getElementById('mass'),k=document.getElementById('stiff');if(m&&k){document.getElementById('massnum').textContent=m.value;document.getElementById('stiffnum').textContent=k.value;document.getElementById('naturalfreq').textContent=(Math.sqrt(Number(k.value)/Number(m.value))).toFixed(2).replace('.',',')};const l=document.getElementById('width'),c=document.getElementById('cond');if(l&&c){document.getElementById('widthnum').textContent=Number(l.value).toFixed(2).replace('.',',');document.getElementById('condnum').textContent=c.value;document.getElementById('heatflow').textContent=(Number(c.value)*30/Number(l.value)).toFixed(2).replace('.',',')}});
  let touchX=0,touchY=0,touchStarted=false;document.addEventListener('touchstart',e=>{if(!e.target.closest('#feed-swipe')||e.target.closest('button,input,select,a')||modal)return;touchStarted=true;touchX=e.changedTouches[0].screenX;touchY=e.changedTouches[0].screenY},{passive:true});document.addEventListener('touchend',e=>{if(!touchStarted||!e.target.closest('#feed-swipe')||e.target.closest('button,input,select,a')||modal){touchStarted=false;return;}touchStarted=false;const dx=e.changedTouches[0].screenX-touchX,dy=e.changedTouches[0].screenY-touchY;if(Math.abs(dy)>65&&Math.abs(dy)>Math.abs(dx)*1.3)nextFeed(dy<0?1:-1);else if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5)nextFeed(dx<0?1:-1)},{passive:true});
  const routes=['videos','subject','home','daily','feed','study','quiz','progress','settings','plan','flash','grades','prep'];
  function restoreRoute(){const hash=location.hash?.replace('#','');if(routes.includes(hash)){captureSim();examMode=null;page=hash;if(hash==='subject'){const state=window.history?.state||{};selectedSubject=subj(state.subject)?state.subject:selectedSubject;selectedTopic=state.topic||null;selectedSubTab=['topics','materials','notes'].includes(state.tab)?state.tab:'topics'}modal=null;render()}}
  window.addEventListener('popstate',restoreRoute);window.addEventListener('hashchange',restoreRoute);
  window.addEventListener('storage',e=>{if(e.key===KEY){storageConflict=true;render()}});
  window.addEventListener('online',()=>showToast('Conexão restabelecida'));window.addEventListener('offline',()=>showToast('Modo offline: seus registros continuam locais'));
  let swRegistration=null;
  function pwaStatus(message){const n=document.getElementById('pwa-status');if(n)n.textContent=message;showToast(message)}
  async function checkUpdate(){try{if(!swRegistration){pwaStatus('Atualização requer HTTPS e Service Worker disponível.');return}await swRegistration.update();pwaStatus(swRegistration.waiting?'Nova versão disponível. Exporte backup e toque em aplicar.':'Verificação solicitada; se uma versão for encontrada, ela ficará aguardando.')}catch(e){pwaStatus('Sem conexão para verificar atualização. O conteúdo local continua disponível.')}}
  function activateUpdate(){if(!swRegistration?.waiting){pwaStatus('Nenhuma atualização aguardando.');return}if(db.activeSim){pwaStatus('Conclua ou descarte o simulado antes de atualizar.');return}if(storageIssue||storageConflict){pwaStatus('Exporte seus dados e resolva o aviso de armazenamento antes de atualizar.');return}if(confirm('Aplicar a nova versão e recarregar? Suas notas e progresso permanecem neste dispositivo.')){navigator.serviceWorker.addEventListener('controllerchange',()=>{const worker=navigator.serviceWorker.controller;const reload=()=>{if(worker?.state==='activated')window.location.reload()};if(worker?.state==='activated')reload();else worker?.addEventListener('statechange',reload)},{once:true});swRegistration.waiting.postMessage({type:'SKIP_WAITING'})}}
  if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').then(r=>{swRegistration=r;if(r.waiting)showToast('Atualização disponível em Configurações');r.addEventListener('updatefound',()=>{r.installing?.addEventListener('statechange',()=>{if(r.waiting&&navigator.serviceWorker.controller)showToast('Nova versão pronta. Aplique em Configurações quando terminar.')})})}).catch(()=>showToast('Conteúdo aberto, mas o modo offline não foi habilitado.'));
  window.addEventListener('orbita-catalog-update',e=>{if(db.activeSim||feedTimer){e.preventDefault();showToast('Termine a sessão ou simulado antes de atualizar o catálogo.')}});
  window.addEventListener('orbita-catalog-ready',()=>{invalidateFeed();feedIndex=0;resetFeed();render()});
  window.addEventListener('orbita-private-card',e=>{const x=e.detail;if(!subj(x.subject)||typeof x.body!=='string'||x.body.length>20000)return;if(db.privateCards.some(c=>c.source?.fileId===x.fileId&&c.body===x.body)){showToast('Este trecho já está na sua biblioteca privada');return;}const card={id:'private-'+Date.now()+'-'+Math.random().toString(36).slice(2),version:1,private:true,subject:x.subject,concept:'source-'+x.fileId,title:x.title,body:x.body,format:'lesson',durationSeconds:90,difficulty:2,prerequisites:[],tags:[x.subject],source:{...x.source,fileId:x.fileId},license:'Privado — acesso autorizado; sem autorização de redistribuição',reviewStatus:'excerpt-unreviewed'};db.privateCards.push(card);save();invalidateFeed();showToast('Trecho adicionado somente à biblioteca privada deste dispositivo')});
  window.addEventListener('orbita-sync',e=>{const {kind,snapshot}=e.detail;if(kind==='notion'&&!snapshot.grades?.length)snapshot.grades=db.imports.notion?.grades||[];const candidate={...db,imports:{...db.imports,[kind]:F.mergeSnapshot(kind,db.imports[kind],snapshot)}};if(writeState(candidate)){db=candidate;invalidateFeed();render();showToast('Dados sincronizados e preservados para estudo offline')}});
  const initial=location.hash?.replace('#','');if(routes.includes(initial)){page=initial;if(initial==='subject'){const state=window.history?.state||{};selectedSubject=subj(state.subject)?state.subject:null;selectedTopic=state.topic||null;selectedSubTab=['topics','materials','notes'].includes(state.tab)?state.tab:'topics'}}
  if(!window.ORBITA_CATALOG&&db.activeSim&&!db.activeSim.ids.every(id=>D.questions.some(q=>q.id===id))){db.activeSim=null;storageIssue='Simulado antigo com questões indisponíveis: exporte um backup para preservar seus dados.'}
  render();window.ORBITA_CONNECTIONS?.bootstrap();
})();
